  "assignment": {
   "title": "여행 경험 인터뷰 녹음",
   "desc": "동태조사 过와 부정형 没(有)…过를 활용해 친구 또는 가족에게 여행 경험을 묻고 답하는 2~3분 분량의 중국어 인터뷰를 녹음합니다. 녹음 파일과 인터뷰 대본(간체자·병음 표기) 문서를 구글 드라이브에 올린 뒤 공유 링크를 제출합니다.",
   "steps": [
    "인터뷰 질문 5개 이상을 간체자와 성조 부호를 붙인 병음으로 작성합니다. 예: 你去过中国吗？(Nǐ qùguo Zhōngguó ma?) / 你吃过北京烤鸭吗？(Nǐ chīguo Běijīng kǎoyā ma?) / 你坐过飞机吗？(Nǐ zuòguo fēijī ma?)",
    "질문마다 긍정 답변(我去过……)과 부정 답변(我没(有)去过……)이 모두 1회 이상 나오도록 예상 답변을 포함한 대본을 완성하고, 过의 위치(동사 바로 뒤)와 부정 시 了를 쓰지 않는 점을 스스로 점검합니다.",
    "파트너와 역할을 나누어 대본을 소리 내어 3회 이상 연습한 뒤, 성조와 过의 경성(guo) 발음에 유의하며 2~3분 분량으로 인터뷰를 녹음합니다.",
    "녹음 파일(mp3/m4a)과 대본 문서를 하나의 구글 드라이브 폴더에 넣고 '링크가 있는 모든 사용자 보기 가능'으로 공유 설정한 뒤, 폴더 공유 링크를 제출합니다."
   ]
  },
