  "assignment": {
   "title": "어제 한 일 말하기 녹음",
   "desc": "동태조사 了, 已经…了, 没(有)를 활용해 '어제 한 일'과 '아직 하지 않은 일'을 소개하는 6~8문장의 중국어 원고(간체자+병음)를 작성하고, 이를 1분 내외로 읽어 녹음합니다. 원고 문서와 녹음 파일을 구글 드라이브의 한 폴더에 올린 뒤, 폴더 공유 링크를 제출합니다.",
   "steps": [
    "원고 작성: 어제 한 일을 시간 순서대로 6~8문장으로 씁니다. 동태조사 了 문장 3개 이상(예: 我昨天看了一个电影。Wǒ zuótiān kànle yí ge diànyǐng.), 已经…了 문장 1개 이상(예: 我已经吃了晚饭了。Wǒ yǐjīng chīle wǎnfàn le.), 没(有) 부정문 1개 이상(예: 我还没(有)做作业。Wǒ hái méi(yǒu) z",
    "병음과 자기 점검: 모든 문장 아래에 성조 부호를 붙인 병음을 달고, 각 了가 동태조사(동작의 완료)인지 어기조사(상황의 변화·완료 확인)인지 문장 옆에 한국어로 짧게 표시합니다.",
    "녹음: 원고를 보며 또박또박 읽어 1분 내외로 녹음합니다(스마트폰 녹음 앱 가능). 了(le)는 경성으로 가볍게, 没(méi)·已经(yǐjīng)의 성조에 유의하고, 첫 문장 앞에 '我叫○○。'로 자기 이름을 밝힙니다.",
    "제출: 원고 문서(구글 문서 또는 PDF)와 녹음 파일(mp3/m4a)을 '12주차_학번_이름' 폴더에 올리고, 공유 설정을 '링크가 있는 모든 사용자 보기 가능'으로 바꾼 뒤 폴더 링크를 과제 게시판에 제출합니다."
   ]
  },
